package io.knowledgebrain.learning;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.learning.progress.v1.*;
import io.knowledgebrain.contracts.learning.session.v1.*;

/** Personal Space learning records; no canonical Roadmap revision is changed. */
final class LearningStudyStore {
 static final Set<String> STATUSES=Set.of("NOT_STARTED","IN_PROGRESS","COMPLETED");
 record Progress(UUID progressId,UUID roadmapId,UUID spaceId,UUID nodeId,String visibility,String status,long version,String updatedAt){}
 record NodeLearning(UUID nodeId,String title,String status,long version,long sessionCount,long recordedSeconds){}
 record Summary(UUID roadmapId,UUID spaceId,long roadmapVersion,List<NodeLearning> nodes,int total,int inProgress,int completed,int percent,long recordedSeconds){}
 record ProgressRevision(UUID revisionId,UUID progressId,long version,UUID actorId,String occurredAt,Progress snapshot){}
 record Session(UUID sessionId,UUID roadmapId,UUID spaceId,UUID nodeId,String nodeTitle,String visibility,String state,long version,String startedAt,String endedAt,long durationSeconds,String note,String createdAt,String updatedAt){}
 record SessionRevision(UUID revisionId,UUID sessionId,long version,UUID actorId,String occurredAt,Session snapshot){}
 record SessionPage(List<Session> items,UUID nextAfter){}
 record Input(UUID nodeId,String startedAt,String endedAt,String note){}
 record Recorded(Session session,boolean created){}
 private final JdbcTemplate jdbc;
 private final TransactionTemplate tx;
 private final Clock clock;
 private final UuidV7 ids;
 private final RoadmapStore roadmaps;
 private final JsonMapper json=JsonMapper.builder().build();

 LearningStudyStore(DataSource ds,Clock clock,RoadmapStore roadmaps){this.jdbc=new JdbcTemplate(ds);this.tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.clock=clock;this.ids=new UuidV7(clock);this.roadmaps=roadmaps;}
 static ResponseStatusException bad(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid learning status, session interval or learning record");}
 static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Learning record unavailable");}
 private static void expected(long current,long expected){if(expected<0)throw bad();if(current!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Learning record changed; inspect latest before saving");}
 private static void trace(String trace){if(trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw bad();}
 private void active(RoadmapStore.Roadmap root){if(!root.state().equals("ACTIVE"))throw missing();}
 private String node(UUID roadmap,UUID node,boolean active){RoadmapGraph.id(node);var rows=jdbc.query("SELECT title FROM roadmap_node WHERE roadmap_id=? AND node_id=?"+(active?" AND state='ACTIVE'":""),(rs,n)->rs.getString(1),roadmap,node);if(rows.isEmpty())throw missing();return rows.getFirst();}

 Summary summary(UUID space,UUID roadmap){RoadmapGraph.id(space);RoadmapGraph.id(roadmap);
  record Row(long version,NodeLearning node){}
  var rows=jdbc.query("SELECT r.version,n.node_id,n.title,coalesce(p.status,'NOT_STARTED'),coalesce(p.version,0),coalesce(s.sessions,0),coalesce(s.seconds,0) FROM roadmap r LEFT JOIN roadmap_node n ON n.roadmap_id=r.roadmap_id AND n.state='ACTIVE' LEFT JOIN node_progress p ON p.roadmap_id=r.roadmap_id AND p.node_id=n.node_id LEFT JOIN (SELECT node_id,count(*) sessions,sum(duration_seconds) seconds FROM study_session WHERE roadmap_id=? AND state='ACTIVE' GROUP BY node_id) s ON s.node_id=n.node_id WHERE r.space_id=? AND r.roadmap_id=? AND r.state='ACTIVE' ORDER BY n.node_id",(rs,n)->new Row(rs.getLong(1),rs.getObject(2)==null?null:new NodeLearning(rs.getObject(2,UUID.class),rs.getString(3),rs.getString(4),rs.getLong(5),rs.getLong(6),rs.getLong(7))),roadmap,space,roadmap);
  if(rows.isEmpty())throw missing();var nodes=rows.stream().map(Row::node).filter(Objects::nonNull).toList();int completed=(int)nodes.stream().filter(n->n.status().equals("COMPLETED")).count(),inProgress=(int)nodes.stream().filter(n->n.status().equals("IN_PROGRESS")).count();long seconds=nodes.stream().mapToLong(NodeLearning::recordedSeconds).sum();return new Summary(roadmap,space,rows.getFirst().version(),nodes,nodes.size(),inProgress,completed,nodes.isEmpty()?0:completed*100/nodes.size(),seconds);
 }
 private Progress readProgress(UUID space,UUID roadmap,UUID node,boolean active){
  var rows=jdbc.query("SELECT p.progress_id,p.version,p.status,v.snapshot::text FROM roadmap r JOIN roadmap_node n ON n.roadmap_id=r.roadmap_id LEFT JOIN node_progress p ON p.roadmap_id=r.roadmap_id AND p.node_id=n.node_id LEFT JOIN node_progress_revision v ON v.progress_id=p.progress_id AND v.version=p.version WHERE r.space_id=? AND r.roadmap_id=? AND n.node_id=?"+(active?" AND r.state='ACTIVE' AND n.state='ACTIVE'":""),(rs,n)->{
   UUID id=rs.getObject(1,UUID.class);if(id==null)return new Progress(null,roadmap,space,node,"PRIVATE","NOT_STARTED",0,null);String raw=rs.getString(4);if(raw==null)throw new IllegalStateException("Progress revision unavailable");var p=json.readValue(raw,Progress.class);if(!p.progressId().equals(id)||!p.roadmapId().equals(roadmap)||!p.spaceId().equals(space)||!p.nodeId().equals(node)||p.version()!=rs.getLong(2)||!p.status().equals(rs.getString(3))||!p.visibility().equals("PRIVATE"))throw new IllegalStateException("Progress revision mismatch");return p;
  },space,roadmap,node);if(rows.isEmpty())throw missing();return rows.getFirst();
 }
 Progress progress(UUID space,UUID roadmap,UUID node){RoadmapGraph.id(space);RoadmapGraph.id(roadmap);RoadmapGraph.id(node);return readProgress(space,roadmap,node,true);}
 Progress progress(UUID space,UUID roadmap,UUID node,UUID actor,long expected,String status,String trace){RoadmapGraph.id(actor);if(status==null||!STATUSES.contains(status))throw bad();trace(trace);return tx.execute(s->{var root=roadmaps.lock(space,roadmap);active(root);var prior=readProgress(space,roadmap,node,true);expected(prior.version(),expected);if(prior.status().equals(status))return prior;var now=clock.instant();var value=new Progress(prior.progressId()==null?ids.next():prior.progressId(),roadmap,space,node,"PRIVATE",status,prior.version()+1,now.toString());if(prior.progressId()==null)jdbc.update("INSERT INTO node_progress VALUES (?,?,?,?,?,?)",value.progressId(),roadmap,node,value.version(),status,Timestamp.from(now));else jdbc.update("UPDATE node_progress SET version=?,status=?,updated_at=? WHERE progress_id=?",value.version(),status,Timestamp.from(now),value.progressId());var revision=ids.next();jdbc.update("INSERT INTO node_progress_revision VALUES (?,?,?,?,?,?::jsonb)",revision,value.progressId(),value.version(),actor,Timestamp.from(now),json.writeValueAsString(value));progressEvent(value,revision,actor,trace,now);return value;});}
 List<ProgressRevision> progressHistory(UUID space,UUID roadmap,UUID node,long before,int limit){readProgress(space,roadmap,node,false);bounds(before,limit);return jdbc.query("SELECT v.revision_id,p.progress_id,v.version,v.actor_id,v.occurred_at,v.snapshot::text FROM node_progress p JOIN node_progress_revision v ON v.progress_id=p.progress_id WHERE p.roadmap_id=? AND p.node_id=? AND v.version<? ORDER BY v.version DESC LIMIT ?",(rs,n)->new ProgressRevision(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getLong(3),rs.getObject(4,UUID.class),rs.getTimestamp(5).toInstant().toString(),json.readValue(rs.getString(6),Progress.class)),roadmap,node,before,limit);}
 private static void bounds(long before,int limit){if(before<1||limit<1||limit>10)throw bad();}

 Input normalize(Input input){if(input==null)throw bad();RoadmapGraph.id(input.nodeId());RoadmapGraph.text("Session",input.note(),8192);try{var start=OffsetDateTime.parse(input.startedAt()).toInstant().truncatedTo(ChronoUnit.SECONDS);var end=OffsetDateTime.parse(input.endedAt()).toInstant().truncatedTo(ChronoUnit.SECONDS);long duration=Duration.between(start,end).getSeconds();if(start.isBefore(Instant.EPOCH)||duration<1||duration>86400||end.isAfter(clock.instant().plusSeconds(300)))throw bad();return new Input(input.nodeId(),start.toString(),end.toString(),input.note());}catch(RuntimeException e){throw bad();}}
 private String fingerprint(Input input){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(input)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException("Digest unavailable");}}
 private Session decode(String raw,UUID space,UUID roadmap,UUID id,long version,String state){if(raw==null)throw new IllegalStateException("Session revision unavailable");var value=json.readValue(raw,Session.class);if(!value.sessionId().equals(id)||!value.spaceId().equals(space)||!value.roadmapId().equals(roadmap)||value.version()!=version||!value.state().equals(state)||!value.visibility().equals("PRIVATE"))throw new IllegalStateException("Session revision mismatch");return value;}
 private Session readSession(UUID space,UUID roadmap,UUID id,boolean active){RoadmapGraph.id(space);RoadmapGraph.id(roadmap);RoadmapGraph.id(id);var rows=jdbc.query("SELECT s.version,s.state,v.snapshot::text FROM roadmap r JOIN study_session s ON s.roadmap_id=r.roadmap_id LEFT JOIN study_session_revision v ON v.session_id=s.session_id AND v.version=s.version WHERE r.space_id=? AND r.roadmap_id=? AND s.session_id=?"+(active?" AND s.state='ACTIVE'":""),(rs,n)->decode(rs.getString(3),space,roadmap,id,rs.getLong(1),rs.getString(2)),space,roadmap,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 Session session(UUID space,UUID roadmap,UUID id){return readSession(space,roadmap,id,true);}
 Recorded record(UUID space,UUID roadmap,UUID actor,String key,Input raw,String trace){RoadmapGraph.id(actor);trace(trace);if(key==null||!key.matches("[0-9a-f]{32}"))throw bad();var input=normalize(raw);String hash=fingerprint(input);return tx.execute(s->{var root=roadmaps.lock(space,roadmap);var existing=jdbc.query("SELECT session_id,request_fingerprint FROM study_session WHERE roadmap_id=? AND request_key=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class),rs.getString(2)),roadmap,key);if(!existing.isEmpty()){var entry=existing.getFirst();if(!entry.getValue().equals(hash))throw new ResponseStatusException(HttpStatus.CONFLICT,"Request key already used for another study session");return new Recorded(readSession(space,roadmap,entry.getKey(),false),false);}active(root);String title=node(roadmap,input.nodeId(),true);var now=clock.instant();var value=new Session(ids.next(),roadmap,space,input.nodeId(),title,"PRIVATE","ACTIVE",1,input.startedAt(),input.endedAt(),Duration.between(Instant.parse(input.startedAt()),Instant.parse(input.endedAt())).getSeconds(),input.note(),now.toString(),now.toString());jdbc.update("INSERT INTO study_session VALUES (?,?,?,'ACTIVE',1,?,?,?,?,?)",value.sessionId(),roadmap,input.nodeId(),Timestamp.from(Instant.parse(value.startedAt())),Timestamp.from(Instant.parse(value.endedAt())),value.durationSeconds(),key,hash);sessionRevision(value,actor,trace,"StudySessionRecorded",now);return new Recorded(value,true);});}
 Session changeSession(UUID space,UUID roadmap,UUID id,UUID actor,long expected,Input raw,boolean retire,String trace){RoadmapGraph.id(actor);trace(trace);var input=retire?null:normalize(raw);return tx.execute(s->{var root=roadmaps.lock(space,roadmap);active(root);var prior=readSession(space,roadmap,id,true);expected(prior.version(),expected);if(!retire&&prior.nodeId().equals(input.nodeId())&&prior.startedAt().equals(input.startedAt())&&prior.endedAt().equals(input.endedAt())&&prior.note().equals(input.note())){node(roadmap,input.nodeId(),true);return prior;}String title=retire?prior.nodeTitle():node(roadmap,input.nodeId(),true);if(!retire&&prior.nodeId().equals(input.nodeId()))title=prior.nodeTitle();var now=clock.instant();var value=new Session(id,roadmap,space,retire?prior.nodeId():input.nodeId(),title,"PRIVATE",retire?"RETIRED":"ACTIVE",prior.version()+1,retire?prior.startedAt():input.startedAt(),retire?prior.endedAt():input.endedAt(),retire?prior.durationSeconds():Duration.between(Instant.parse(input.startedAt()),Instant.parse(input.endedAt())).getSeconds(),retire?prior.note():input.note(),prior.createdAt(),now.toString());jdbc.update("UPDATE study_session SET node_id=?,state=?,version=?,started_at=?,ended_at=?,duration_seconds=? WHERE session_id=?",value.nodeId(),value.state(),value.version(),Timestamp.from(Instant.parse(value.startedAt())),Timestamp.from(Instant.parse(value.endedAt())),value.durationSeconds(),id);sessionRevision(value,actor,trace,retire?"StudySessionRetired":"StudySessionUpdated",now);return value;});}
 SessionPage sessions(UUID space,UUID roadmap,UUID after,int limit){roadmaps.inspect(space,roadmap);if(after!=null)RoadmapGraph.id(after);if(limit<1||limit>100)throw bad();var args=after==null?new Object[]{space,roadmap,limit+1}:new Object[]{space,roadmap,after,limit+1};var rows=jdbc.query("SELECT s.session_id,s.version,s.state,v.snapshot::text FROM roadmap r JOIN study_session s ON s.roadmap_id=r.roadmap_id LEFT JOIN study_session_revision v ON v.session_id=s.session_id AND v.version=s.version WHERE r.space_id=? AND r.roadmap_id=? AND s.state='ACTIVE'"+(after==null?"":" AND s.session_id>?")+" ORDER BY s.session_id LIMIT ?",(rs,n)->decode(rs.getString(4),space,roadmap,rs.getObject(1,UUID.class),rs.getLong(2),rs.getString(3)),args);var page=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new SessionPage(page,rows.size()>limit?page.getLast().sessionId():null);}
 List<SessionRevision> sessionHistory(UUID space,UUID roadmap,UUID id,long before,int limit){readSession(space,roadmap,id,false);bounds(before,limit);return jdbc.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM study_session_revision WHERE session_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new SessionRevision(rs.getObject(1,UUID.class),id,rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Session.class)),id,before,limit);}

 private void progressEvent(Progress p,UUID revision,UUID actor,String trace,Instant now){var payload=ProgressChangedPayloadV1.newBuilder().setProgressId(p.progressId().toString()).setRevisionId(revision.toString()).setRoadmapId(p.roadmapId().toString()).setNodeId(p.nodeId().toString()).setVersion(p.version()).setStatus(p.status()).setVisibility("PRIVATE").setUpdatedAt(p.updatedAt()).build();var envelope=ProgressEventEnvelopeV1.newBuilder().setEventId(ids.next().toString()).setEventType("LearningProgressChanged").setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("learning-service").setAggregateType("LearningProgress").setAggregateId(p.progressId().toString()).setSpaceId(p.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload.toByteString()).build();outbox(UUID.fromString(envelope.getEventId()),"progress",p.progressId(),"LearningProgressChanged","progress-events",trace,now,envelope.toByteArray());}
 private void sessionRevision(Session value,UUID actor,String trace,String type,Instant now){var revision=ids.next();jdbc.update("INSERT INTO study_session_revision VALUES (?,?,?,?,?,?::jsonb)",revision,value.sessionId(),value.version(),actor,Timestamp.from(now),json.writeValueAsString(value));var payload=StudySessionChangedPayloadV1.newBuilder().setSessionId(value.sessionId().toString()).setRevisionId(revision.toString()).setRoadmapId(value.roadmapId().toString()).setNodeId(value.nodeId().toString()).setNodeTitle(value.nodeTitle()).setVersion(value.version()).setState(value.state()).setVisibility("PRIVATE").setStartedAt(value.startedAt()).setEndedAt(value.endedAt()).setDurationSeconds(value.durationSeconds()).setNote(value.note()).setCreatedAt(value.createdAt()).setUpdatedAt(value.updatedAt()).build();var envelope=StudySessionEventEnvelopeV1.newBuilder().setEventId(ids.next().toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("learning-service").setAggregateType("StudySession").setAggregateId(value.sessionId().toString()).setSpaceId(value.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(payload.toByteString()).build();outbox(UUID.fromString(envelope.getEventId()),"study-session",value.sessionId(),type,"study-session-events",trace,now,envelope.toByteArray());}
 private void outbox(UUID event,String aggregate,UUID id,String type,String artifact,String trace,Instant now,byte[] payload){jdbc.update("INSERT INTO outbox_event VALUES (?,?,?,?,?,?,'learning',?,'1',?)",event,aggregate,id,type,Timestamp.from(now),trace,artifact,payload);}
}
